// MIT. Complete case/source package tools, using the original Support owner.
const id={type:'string',pattern:'^[a-z0-9][a-z0-9_-]{0,63}$'};
const sha={type:'string',pattern:'^[a-f0-9]{64}$'};
const uuid={type:'string',pattern:'^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$'};
const actor={type:'string',minLength:1,maxLength:200};
const page={offset:{type:'integer',minimum:0},limit:{type:'integer',minimum:1,maximum:200},
  q:{type:'string',maxLength:240}};
const source={type:'object',properties:{kind:{enum:['input','operation']},id},required:['kind','id'],additionalProperties:false};
const fileRead={source,name:{type:'string',minLength:1,maxLength:4096},expectedManifestSha256:sha,
  expectedSha256:sha,readId:uuid,offset:{type:'integer',minimum:0},limit:{type:'integer',minimum:1,maximum:196608}};
export function casePackageTools(tool) {
  const read={readOnly:true,idempotent:true},write={idempotent:true};
  return [
    tool('merchant_case_package_catalog','Inspect the original complete-package owner, configured Handoffs source aliases, source-owned byte limits and existing private case/source paths. Starts no transfer.',{},[],read),
    tool('merchant_case_package_operations','Page retained package operations and their observed lifecycle. A saved RUNNING state alone does not establish a live worker.',page,[],read),
    tool('merchant_case_package_inputs','Page original browser-received complete package inputs. Their original manifest and native member bytes remain retained.',page,[],read),
    tool('merchant_case_package_status','Read one original operation, actual ownership in this process, native receiving progress and completion.',{id},['id'],read),
    tool('merchant_case_package_prepare','Retain one complete package operation. Export selects an original saved case revision and preserves full history/all native source bundles. Inspect/receive selects an existing input or exported operation. Remote receiving uses one configured Handoffs source and original export. Keep this exact ID, actor and body after an interrupted reply.',
      {id,kind:{enum:['export','inspect','receive','remote']},actor,caseId:uuid,revision:sha,source,
        expectedManifestSha256:sha,profile:id,exportId:id},['id','kind','actor'],write),
    tool('merchant_case_package_run','Start or join the exact retained operation through the original writer lease. Completed requests retain their first native result. Inspect status after a lost reply.',{id},['id'],write),
    tool('merchant_case_package_pause','Pause the running package operation owned by this installed process and retain its native checkpoints. It cannot stop another owner.',{id},['id'],write),
    tool('merchant_case_package_inventory','Page complete files, original immutable case revisions or every native source bundle, including historical and unassigned attachments.',
      {source,expectedManifestSha256:sha,section:{enum:['files','sourceBundles','originalFiles','revisions']},bundleId:sha,manifestSha256:sha,...page},['source','expectedManifestSha256'],read),
    tool('merchant_case_package_remote_inspect','Read the exact complete package manifest from a host-configured original Handoffs source. Returns original identity and full inventory; creates no local case.',
      {profile:id,exportId:id},['profile','exportId'],{...read,openWorld:true}),
    tool('merchant_case_package_open','Resolve the completed receiving operation to its current original saved case. Preserves any later receiver edits and returns the independently usable source directory.',
      {id},['id'],read),
    tool('merchant_case_package_file','Read a bounded range of one whole-package file using the original immutable descriptor reader. Continue its readId or reopen the same expected SHA/offset after expiry. Large native source archives stay streamed.',
      fileRead,['source','name','expectedManifestSha256','expectedSha256'],read),
    tool('merchant_case_package_original_file','Read an actual original member inside one package-declared native source bundle after that source is available in the original local source service. This includes unassigned historical attachments.',
      {source,expectedManifestSha256:sha,bundleId:sha,manifestSha256:sha,path:{type:'string',maxLength:4096},
        expectedSha256:sha,readId:uuid,offset:{type:'integer',minimum:0},limit:{type:'integer',minimum:1,maximum:196608}},
      ['source','expectedManifestSha256','bundleId','manifestSha256','path','expectedSha256'],read),
    tool('merchant_case_package_file_release','Release an original immutable file reader owned by this package selection.',{source,readId:uuid},['source','readId'],write),
    tool('merchant_case_package_export_manifest','Read the original complete-export manifest descriptor for native receiving. Fetch case-source-package.json through the original leased file route; its complete inventory includes all retained native bundles.',
      {exportId:id},['exportId'],read),
    tool('merchant_case_package_export_file','Read a complete export file through the original retained-download protocol. All names and SHA identities are bound to the exact completion manifest.',
      {exportId:id,file:{type:'string',maxLength:4096},expectedManifestSha256:sha,expectedSha256:sha,
        readId:uuid,offset:{type:'integer',minimum:0},limit:{type:'integer',minimum:1,maximum:196608}},
      ['exportId','file','expectedManifestSha256','expectedSha256'],read),
    tool('merchant_case_package_export_file_release','Release an original export file lease.',{exportId:id,readId:uuid},['exportId','readId'],write)
  ];
}

// MIT. Original full pricing and quotation receiving on the configured merchant case.
const uuid={type:'string',pattern:'^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$'};
const sha={type:'string',pattern:'^[a-f0-9]{64}$'};
const text=maxLength=>({type:'string',minLength:1,maxLength});
const path=text(4096),selected={id:uuid,expectedRevision:sha};
const quoted={...selected,revision:sha,quoteId:uuid,quoteSha256:sha,archiveSha256:sha};
export function commercialReceivingTools(tool){
  const read={readOnly:true,idempotent:true},write={idempotent:true};
  return [
    tool('merchant_case_commercial_receiving_status','Read the current original case identity and actual in-process pricing/backup receiving work. Saved backup and case request IDs remain in their original native engines.',
      {id:uuid},['id'],read),
    tool('merchant_case_commercial_receiving_capture','Capture an existing saved SF97 plan and its complete original WORKSPACE_BACKUP. Supply the original private workspace/config and exactly one saved snapshot/history path. Keep backupRequestId, selected inputs and output directory after interruption. Inspect the retained source before attaching it.',
      {...selected,pricingDirectory:path,pricingConfig:path,pricingSnapshot:path,pricingHistory:path,
        planId:uuid,scenarioId:text(200),backupRequestId:uuid,directory:path},
      ['id','pricingDirectory','pricingConfig','planId','backupRequestId','directory'],write),
    tool('merchant_case_commercial_receiving_inspect','Verify the complete original retained pricing source, full workspace backup, original cost edition and supplier files. Returns exact source/file descriptors and the native pricing review; it does not append to the merchant case.',
      {...selected,directory:path,expectedSourceSha256:sha},['id','directory'],read),
    tool('merchant_case_commercial_receiving_attach','Attach the reviewed pricing source and complete original backup to this same case using the original two native request UUIDs. Record the merchant/source binding reason. Retry both original IDs, original case revision, actor, source SHA and exact input after a lost reply.',
      {...selected,directory:path,expectedSourceSha256:sha,pricingRequestId:uuid,attachmentRequestId:uuid,
        actor:text(200),bindingReason:text(4000)},
      ['id','expectedRevision','directory','expectedSourceSha256','pricingRequestId','attachmentRequestId','actor','bindingReason'],write),
    tool('merchant_case_commercial_receiving_case','Inspect one exact original quote and its retained complete pricing backup at a saved case revision. Choose archiveSha256 when the source has multiple original backups. Customer responses and source-case lineage remain unchanged.',
      quoted,['id','quoteId','quoteSha256'],read),
    tool('merchant_case_commercial_receiving_restore','Recover the original pricing TAR from the selected quote and restore its complete editable SF97 workspace through the original archive engine. Keep the retained archive outside the restore directory. Reopen verifies the same plan, pricing version, cost edition and every original supplier source.',
      {...quoted,archive:path,directory:path},['id','quoteId','quoteSha256','archive','directory'],write),
  ];
}

import {commercialReceivingTools} from './commercial-receiving.mjs';
// MIT. Quotation controls use the configured original SF74 case writer.
import {MAX_MATERIAL_BYTES} from '../../../stellar/scf-starforge-20261009/sf74-merchant-support-console/commissioning.mjs';
import {MAX_RETAINED_CHUNK_BYTES} from '../retained-file-contracts.mjs';
const uuid={type:'string',pattern:'^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$'};
const digest={type:'string',pattern:'^[a-f0-9]{64}$'};
const text=maxLength=>({type:'string',maxLength});
const object=(properties,required=Object.keys(properties))=>({type:'object',properties,required,additionalProperties:false});
const nullable=value=>({anyOf:[value,{type:'null'}]});
const rows=items=>({type:'array',maxItems:500,items});
const draft=object({parentId:nullable(uuid),title:text(400),customer:object({name:text(500),contact:text(2000)}),
  currency:{const:'USD'},implementationSourceId:text(200),serviceSourceId:text(200),pricingSourceId:text(200),validThrough:text(10),
  implementation:object({lines:rows(object({id:text(200),taskId:nullable(text(200)),title:text(2400),hours:text(40),rateUsd:text(40)}))}),
  service:object({period:{const:'MONTH'},lines:rows(object({id:text(200),commitmentId:nullable(text(200)),title:text(2400),quantity:text(40),unitUsd:text(40)}))}),
  pricing:object({routes:rows(object({routeId:text(200),monthlyRequests:text(24)}))}),
  terms:object({scope:text(64000),deliverables:text(64000),exclusions:text(64000),payment:text(64000),acceptance:text(64000)}),
  notes:text(16000)});
const selected={id:uuid,expectedRevision:digest},change={...selected,requestId:uuid,actor:text(200)};
const implementationSelection={quoteId:uuid,quoteSha256:digest,acceptanceId:uuid,
  resolutions:{type:'object',additionalProperties:{enum:['accepted','current']}}};
export function commercialTools(tool) {
  const read={readOnly:true,idempotent:true},write={idempotent:true};
  return [
    ...commercialReceivingTools(tool),
    tool('merchant_case_commercial','Open the complete original saved quotation workspace: implementation editions, service terms, received SF97 pricing sources, unfinished draft, immutable quotes, actual customer responses and accepted-quote implementation adoption. Keep its current case revision for a new change.',
      {id:uuid,revision:digest},['id'],read),
    tool('merchant_case_commercial_preview','Review explicit work hours, service fees and monthly route requests against the retained original sources. Returns exact decimal calculations, a customer-readable proposal and reviewSha256. No case write.',
      {...selected,draft},['id','expectedRevision','draft'],read),
    tool('merchant_case_commercial_save_draft','Retain the complete unfinished quotation as an original implementation material. Keep requestId, actor, original case revision and exact draft across an interrupted reply; the original event replays after later edits.',
      {...change,draft},['id','expectedRevision','requestId','actor','draft'],write),
    tool('merchant_case_commercial_publish','Save an immutable quote edition from the exact reviewed draft and source bindings. A revision names its original parent. Customer acceptance is a separate recorded response.',
      {...change,draft,reviewSha256:digest,parentId:nullable(uuid)},['id','expectedRevision','requestId','actor','draft','reviewSha256'],write),
    tool('merchant_case_commercial_receive_pricing','Receive all five exact source files exported from an existing original SF97 saved plan. The source reproduces the native scenario review and binds its original save request. Retain the complete sourceText, sourceSha256 and same request UUID after a lost reply.',
      {...change,sourceText:text(MAX_MATERIAL_BYTES),sourceSha256:digest},
      ['id','expectedRevision','requestId','actor','sourceText','sourceSha256'],write),
    tool('merchant_case_commercial_receive','Record an actual customer acceptance, requested revision or decline for the exact immutable quotation bytes. Include the original response time and source reference. This preserves the implementation and service receiving states.',
      {...change,quoteId:uuid,quoteSha256:digest,status:{enum:['ACCEPTED','REVISION_REQUESTED','DECLINED']},
        observedAt:text(24),source:text(4096),note:text(16000)},
      ['id','expectedRevision','requestId','actor','quoteId','quoteSha256','status','observedAt','source'],write),
    tool('merchant_case_commercial_preview_implementation','Preview how an accepted quote creates or updates the saved implementation. Returns changes, conflicts and reviewSha256. Resolutions select accepted or current values using the returned conflict keys.',
      {...selected,...implementationSelection},['id','expectedRevision','quoteId','quoteSha256'],read),
    tool('merchant_case_commercial_adopt_implementation','Apply the reviewed accepted quote through the original case writer. Keep the exact case revision, immutable quote, recorded acceptance, reviewSha256, resolutions and requestId for identical recovery after an interrupted reply.',
      {...change,...implementationSelection,reviewSha256:digest,note:text(16000)},
      ['id','expectedRevision','requestId','actor','quoteId','quoteSha256','acceptanceId','reviewSha256'],write),
    tool('merchant_case_commercial_compare','Compare two retained quote editions, exact decimal amounts, original source bindings, customer terms and their recorded responses.',
      {...selected,beforeId:uuid,afterId:uuid},['id','expectedRevision','beforeId','afterId'],read),
    tool('merchant_case_commercial_file','Read a complete retained customer Markdown or machine quotation through the original bounded file reader. The exact saved case revision reopens after later edits. Continue with readId, expectedSha256 and nextOffset; cold reopen uses the same selection and expectedSha256. Use merchant_case_export for the complete case.',
      {id:uuid,revision:digest,quoteId:uuid,quoteSha256:digest,kind:{enum:['QUOTE','QUOTE_JSON']},
        readId:uuid,expectedSha256:digest,offset:{type:'integer',minimum:0},limit:{type:'integer',minimum:1,maximum:MAX_RETAINED_CHUNK_BYTES}},
      ['id','revision','quoteId','quoteSha256','kind'],read),
    tool('merchant_case_commercial_file_reads','List current original quotation file reads for this case, including exact descriptors and continuation IDs.',
      {id:uuid},['id'],read),
    tool('merchant_case_commercial_file_release','Close an original quotation file read after partial receiving. The immutable quote stays in the saved case for later reopen.',
      {id:uuid,readId:uuid},['id','readId'],write),
  ];
}

// MIT. Original tool metadata; provider runtimes load only when selected.


const HASH = /^[a-f0-9]{64}$/;

const ID = /^[a-z0-9][a-z0-9_-]{0,63}$/;

const releaseId = { type: 'string', pattern: ID.source };

const digest = { type: 'string', pattern: HASH.source };

const selected = { releaseId };

const expected = { ...selected, expectedDigest: digest };

const current = { expectedSnapshot: digest, expectedRevision: { type: 'integer', minimum: 1 } };

const read = { readOnly: true, idempotent: true };

function datasetReleaseView(dataset) {
  if (!dataset) return null;
  const { datasetDirectory, ...publicValue } = dataset;
  return { ...publicValue, controllerConfigured: typeof datasetDirectory === 'string' };
}

function datasetLifecycleTools(tool) {
  return [
    tool('merchant_dataset_status', 'Read the retained SF82 dataset release and its running original version controller: staged baseline, current snapshot/revision, retained versions and actual resources. A stopped controller is reported without opening a writer.',
      selected, ['releaseId'], read),
    tool('merchant_dataset_initialize', 'Initialize the original version store from an exact staged release before first seller start. Reuses an existing running controller; reopens an existing stopped store under its original writer lease and closes immediately. Existing data selection is preserved.',
      expected, ['releaseId', 'expectedDigest'], { idempotent: true }),
    tool('merchant_dataset_preview', 'Query the running original controller with its native URL query string, including retained snapshot and cursor continuity. Returns the original operator preview through the same dataset parser.',
      { ...selected, query: { type: 'string', maxLength: 8192 } }, ['releaseId', 'query'], read),
    tool('merchant_dataset_publish', 'Publish the dataset in an exact staged SF82 release through its original running controller, using current native snapshot/revision. Original contract, retention and capacity checks apply. Running payment terms change through merchant_activate/restart.',
      { ...expected, ...current }, ['releaseId', 'expectedDigest', 'expectedSnapshot', 'expectedRevision']),
    tool('merchant_dataset_activate', 'Select a retained data snapshot through the original controller using current snapshot/revision. In-flight requests keep their admitted generation. Merchant release selection and payment terms use the existing SF82 lifecycle.',
      { ...expected, ...current, snapshot: digest },
      ['releaseId', 'expectedDigest', 'snapshot', 'expectedSnapshot', 'expectedRevision']),
  ];
}

export { datasetLifecycleTools, datasetReleaseView, selected, read, expected, current, digest, releaseId, HASH, ID };

// MIT. Complete service case operator contract; original SF74/SF93 modules execute.
const uuid={type:'string',pattern:'^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$'};
const digest={type:'string',pattern:'^[a-f0-9]{64}$'};
const alias={type:'string',pattern:'^[A-Za-z0-9_-]{1,64}$'};
const text=maxLength=>({type:'string',maxLength});
const integer=(minimum=0,maximum=Number.MAX_SAFE_INTEGER)=>({type:'integer',minimum,maximum});
const object=(properties,required=Object.keys(properties))=>({type:'object',properties,required,additionalProperties:false});
const nullable=value=>({anyOf:[value,{type:'null'}]});
const utc={type:'string',pattern:'^\\d{4}-\\d\\d-\\d\\dT\\d\\d:\\d\\d:\\d\\d\\.\\d{3}Z$'};
const date={type:'string',pattern:'^\\d{4}-\\d\\d-\\d\\d$'};
const windows={type:'array',maxItems:12,items:object({start:text(5),end:text(5)})};
const calendar=object({mode:{enum:['always','business']},timeZone:text(100),
  week:{type:'array',maxItems:7,items:object({day:integer(1,7),windows})},
  exceptions:{type:'array',maxItems:1000,items:object({date,windows})}});
const kinds=['ENDPOINT_UNAVAILABLE','OBSERVER_INCOMPLETE','HTTP_5XX','DISCONNECTED','DELIVERY_UNAVAILABLE','DELIVERY_BACKLOG','DELIVERY_EXHAUSTED'];
const terms=object({id:uuid,expectedRevision:nullable(integer(1)),title:text(500),customer:text(500),owner:text(240),reference:text(4000),
  status:{enum:['proposed','active','ended']},incidentSourceId:alias,merchantId:alias,merchantBinding:digest,
  effectiveFrom:utc,effectiveUntil:nullable(utc),calendar,
  targets:{type:'array',minItems:1,maxItems:7,items:object({kind:{enum:kinds},responseMinutes:integer(1,527040),recoveryMinutes:integer(1,527040)})},
  reviewedBy:text(240),note:text(8000)});
const capture=object({incidentSource:{type:'string',pattern:'^[a-z0-9][a-z0-9_-]{0,63}$'},merchantId:alias,
  expectedSourceRevision:integer(1),expectedConfigHash:digest,expectedMerchantBinding:digest},
  ['merchantId','expectedSourceRevision','expectedConfigHash','expectedMerchantBinding']);
const exclusion=object({id:uuid,incidentId:uuid,captureSha256:digest,from:utc,through:utc,
  scope:{enum:['response','recovery','both']},reason:text(4000),reference:text(4000),reviewedBy:text(240)});
const selection=object({termsId:uuid,termsRevision:integer(1),from:date,through:date,asOf:utc,
  captureSha256s:{type:'array',minItems:1,maxItems:1000,items:digest},
  exclusionIds:{type:'array',maxItems:1000,items:uuid}});
const report=object({...selection.properties,expectedPreviewSha256:digest,reviewedBy:text(240),note:text(8000)});
export function serviceTools(tool){
  const read={readOnly:true,idempotent:true};
  return [
    tool('merchant_support_service_snapshot','Read one complete original merchant incident history in its configured SF93 store transaction. Includes current or retired registration, source/config revisions and exact merchant binding for the next capture. Starts no watcher.',
      {incidentSource:capture.properties.incidentSource,merchantId:alias},['merchantId'],read),
    tool('merchant_service_read','Read the original saved case service summary or page through terms, captures, exclusions, reports and operator changes. recordId returns the complete selected original record; use its SHA to select one terms edition. Complete case exports preserve every source and unfinished form.',
      {id:uuid,revision:digest,section:{enum:['summary','terms','captures','exclusions','reports','operations']},
        recordId:text(64),offset:integer(),limit:integer(1,100)},['id'],read),
    tool('merchant_service_change','Save a reviewed service change through the original case writer. action selects terms, capture, exclusion or report and the matching input object. Capture guards the inspected source/config/merchant binding. Retain the same requestId, expectedRevision and input after a lost response; exact replay returns the original result even after later case changes.',
      {id:uuid,expectedRevision:digest,requestId:uuid,action:{enum:['terms','capture','exclusion','report']},
        input:{anyOf:[terms,capture,exclusion,report]}},
      ['id','expectedRevision','requestId','action','input'],{idempotent:true}),
    tool('merchant_service_preview','Calculate a complete service report from an exact current case, terms history, selected original incident captures, named calendar and explicitly reviewed exclusions. Its previewSha256 binds the subsequent retained report.',
      {id:uuid,expectedRevision:digest,selection},['id','expectedRevision','selection'],read),
    tool('merchant_service_report','Render one retained original service report as complete JSON, incident CSV or printable HTML. Returns exact UTF-8 bytes/hash and filename; original reports and all selected sources stay in the case export.',
      {id:uuid,revision:digest,reportId:uuid,format:{enum:['json','csv','html']}},['id','reportId'],read)
  ];
}

import {commercialTools} from './commercial.mjs';
import {casePackageTools} from './case-packages.mjs';
// MIT. Original tool metadata; provider runtimes load only when selected.
import { CASE_STATUSES } from '../../../stellar/scf-starforge-20261009/sf74-merchant-support-console/case-statuses.mjs';
import { MAX_RETAINED_CHUNK_BYTES } from '../retained-file-contracts.mjs';
import {serviceTools} from './service.mjs';

const uuid = { type: 'string', pattern: '^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$' };

const digest = { type: 'string', pattern: '^[a-f0-9]{64}$' };

const alias = { type: 'string', pattern: '^[a-z0-9][a-z0-9_-]{0,63}$' };

const text = maximum => ({ type: 'string', maxLength: maximum });

const object = properties => ({ type: 'object', properties, additionalProperties: false });

const metadataSchema = object({ merchant: text(480), owner: text(480), status: { enum: CASE_STATUSES },
  followUpOn: text(10), nextAction: text(2400), notes: text(16000) });

const termsSchema = { ...object({ workOrderRef: text(120), sellerDisplayName: text(200), relationshipOwner: text(200),
  proposedWindow: text(8192), delivery: object({ scope: text(8192), deliverables: text(8192), acceptanceCriteria: text(8192) }),
  merchantConsent: { ...object({ status: { enum: ['NOT_RECORDED', 'CONFIRMED'] }, receiptUrl: { type: ['string', 'null'], maxLength: 8192 } }), required: ['status'] },
  commercial: { ...object({ priceApproval: { enum: ['NOT_APPROVED', 'OWNER_APPROVED_PROPOSAL'] }, feeUsd: { type: ['number', 'null'] },
    costUsd: { type: ['number', 'null'] }, approvalReceiptUrl: { type: ['string', 'null'], maxLength: 8192 } }), required: ['priceApproval'] } }),
  required: ['merchantConsent', 'commercial'] };

const selected = { id: uuid, expectedRevision: digest };

const page = { offset: { type: 'integer', minimum: 0 }, limit: { type: 'integer', minimum: 1, maximum: 100 } };

const notificationStatuses = ['PENDING', 'RETRY', 'IN_FLIGHT', 'PAUSED', 'EXHAUSTED', 'DELIVERED', 'CANCELLED'];
const incidentSource = { ...alias, description: 'Original host-declared incident source ID. Required when multiple sources have no host default.' };
const sourceTools = new Set(['merchant_support_profiles', 'merchant_support_configure', 'merchant_support_watch_status',
  'merchant_support_watch_start', 'merchant_support_watch_stop', 'merchant_notifications', 'merchant_incident_notify',
  'merchant_notification_update', 'merchant_incidents', 'merchant_incident_ack', 'merchant_incident_case']);

function supportTools(tool) {
  const read = { readOnly: true, idempotent: true };
  return [
    ...serviceTools(tool),
    ...casePackageTools(tool),
    ...commercialTools(tool),
    tool('merchant_support_incident_sources', 'Inspect the original support connection mode, configured incident source IDs/labels, bound source-file digest and host default. Reads no arbitrary path and starts no watcher.', {}, [], read),
    tool('merchant_support_destination', 'Inspect the currently selected source notification configuration at its exact revision. Slack resolves the original host token and reads the actual authenticated workspace/channel; webhook reports configuration resolution. Sends no notification.',
      { incidentSource, expectedConfigRevision: { type: 'integer', minimum: 1 } }, ['expectedConfigRevision'], { ...read, openWorld: true }),
    tool('merchant_incident_view', 'Open one retained original incident with its current revision, last notification ID, sanitized events and actual advertised routes from before/after capture files. Returns capture issues without replacing the original files or observing a seller.',
      { incidentSource, id: uuid }, ['id'], read),
    tool('merchant_support_profiles', 'List host-declared SF93 registration profiles, or inspect one original compiled configuration, its file digest, current configuration revision and actual changes. Notification values remain environment references.',
      { profile: alias }, [], read),
    tool('merchant_support_configure', 'Apply an inspected host profile through the original SF93 configuration transaction. Requires its exact source digest and current configuration revision. After a lost reply, inspect the current configuration before another change.',
      { profile: alias, expectedSourceSha256: digest, expectedConfigRevision: { type: 'integer', minimum: 1 } }, ['profile', 'expectedSourceSha256', 'expectedConfigRevision']),
    tool('merchant_support_watch_status', 'Read the original watcher record and this MCP operator\'s actual ownership. A saved RUNNING record alone does not establish a live worker or ownership by this operator.', {}, [], read),
    tool('merchant_support_watch_start', 'Start the ORIGINAL SF93 watcher for the exact inspected configuration. It acquires the existing kernel lease, polls configured local merchant endpoints and sends the existing configured incident notifications. Does not start a seller or delivery worker.',
      { expectedConfigRevision: { type: 'integer', minimum: 1 }, expectedConfigHash: digest }, ['expectedConfigRevision', 'expectedConfigHash']),
    tool('merchant_support_watch_stop', 'Stop only the original watcher started by this MCP process, using its exact instance ID. Waits for its original final state write and lease release. An identical completed stop can be reopened.',
      { instanceId: uuid }, ['instanceId'], { idempotent: true }),
    tool('merchant_notifications', 'Page through original incident notification records without message bodies, destination URLs or signing keys. Includes actual attempt counts, state and retry reason for recovery.',
      { id: uuid, incidentId: uuid, status: { enum: notificationStatuses }, ...page }, [], read),
    tool('merchant_incident_notify', 'Queue a NEW original reminder for the exact incident revision and current destination. Pass the latest expectedNotificationId from merchant_incident_view, or null when none exists, to atomically reject duplicate reminders after a lost response. Source-file mode requires that guard; legacy single-store callers may omit it.',
